export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuffer = null;
    this.lastHit = 0;
    this.lastShoot = 0;
    this.musicTimer = 0;
    this.step = 0;
    this.playing = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.34;
      this.master.connect(this.ctx.destination);
      this.makeNoise();
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
    } catch {
      this.ctx = null;
    }
  }

  makeNoise() {
    if (!this.ctx) return;
    const length = Math.floor(this.ctx.sampleRate * 0.5);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buffer;
  }

  setMuted(value) {
    this.muted = value;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(value ? 0 : 0.34, this.ctx.currentTime, 0.02);
    }
  }

  tone({ freq = 440, to = null, dur = 0.1, type = 'sine', vol = 0.1, delay = 0, attack = 0.004 }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (to !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise({ dur = 0.1, vol = 0.08, freq = 900, q = 1, delay = 0 }) {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  ui() {
    this.tone({ freq: 660, to: 880, dur: 0.055, type: 'triangle', vol: 0.045 });
  }

  shoot() {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.lastShoot < 55) return;
    this.lastShoot = now;
    this.tone({ freq: 960, to: 1480, dur: 0.055, type: 'triangle', vol: 0.022 });
  }

  hit(big = false) {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.lastHit < 38) return;
    this.lastHit = now;
    this.noise({ dur: big ? 0.12 : 0.055, vol: big ? 0.09 : 0.035, freq: big ? 420 : 1500, q: 0.8 });
    if (big) this.tone({ freq: 150, to: 60, dur: 0.16, type: 'sawtooth', vol: 0.05 });
  }

  hurt() {
    this.tone({ freq: 180, to: 70, dur: 0.3, type: 'sawtooth', vol: 0.11 });
    this.noise({ dur: 0.18, vol: 0.09, freq: 300, q: 0.7 });
  }

  pickup(tier = 1) {
    const notes = tier >= 4 ? [523, 659, 784, 1046, 1318] : tier === 3 ? [440, 554, 659, 880] : tier === 2 ? [392, 523, 659] : [330, 440];
    notes.forEach((f, i) => this.tone({ freq: f, dur: 0.16, type: 'triangle', vol: 0.055, delay: i * 0.055 }));
    if (tier >= 4) {
      this.tone({ freq: 1046, dur: 0.8, type: 'sine', vol: 0.045, delay: 0.22 });
      this.noise({ dur: 0.5, vol: 0.035, freq: 3000, q: 1.6, delay: 0.04 });
    }
  }

  levelup() {
    [392, 523, 659, 784, 1046].forEach((f, i) => this.tone({ freq: f, dur: 0.24, type: 'triangle', vol: 0.06, delay: i * 0.065 }));
    this.noise({ dur: 0.45, vol: 0.045, freq: 2400, q: 1.2 });
  }

  ability() {
    this.tone({ freq: 240, to: 880, dur: 0.28, type: 'sawtooth', vol: 0.05 });
    this.tone({ freq: 480, to: 1320, dur: 0.24, type: 'triangle', vol: 0.035, delay: 0.03 });
  }

  wave() {
    this.tone({ freq: 110, to: 90, dur: 0.5, type: 'sawtooth', vol: 0.055 });
    this.tone({ freq: 220, to: 180, dur: 0.5, type: 'triangle', vol: 0.04, delay: 0.05 });
  }

  boss() {
    this.tone({ freq: 82, to: 48, dur: 1.3, type: 'sawtooth', vol: 0.12 });
    this.tone({ freq: 123, to: 70, dur: 1.1, type: 'square', vol: 0.045, delay: 0.15 });
    this.noise({ dur: 0.9, vol: 0.06, freq: 180, q: 0.6 });
  }

  explode() {
    this.noise({ dur: 0.22, vol: 0.09, freq: 240, q: 0.5 });
    this.tone({ freq: 110, to: 42, dur: 0.25, type: 'sine', vol: 0.07 });
  }

  death() {
    [330, 247, 196, 147, 98].forEach((f, i) => this.tone({ freq: f, dur: 0.4, type: 'triangle', vol: 0.06, delay: i * 0.12 }));
    this.noise({ dur: 0.9, vol: 0.045, freq: 400, q: 0.5, delay: 0.1 });
  }

  music(dt) {
    if (!this.ctx || this.muted || !this.playing) return;
    this.musicTimer -= dt;
    if (this.musicTimer > 0) return;
    this.musicTimer = 0.28;
    const scale = [55, 65.41, 73.42, 82.41, 98, 110, 130.81, 146.83];
    const step = this.step++;
    if (step % 8 === 0) {
      this.tone({ freq: scale[0], to: scale[0] * 0.98, dur: 0.9, type: 'sine', vol: 0.035 });
      this.tone({ freq: scale[0] * 2, dur: 0.7, type: 'triangle', vol: 0.015 });
    }
    if (step % 2 === 0) {
      const note = scale[(step * 3 + 2) % scale.length] * 4;
      this.tone({ freq: note, dur: 0.22, type: 'triangle', vol: 0.009 });
    }
    if (step % 8 === 4) this.noise({ dur: 0.08, vol: 0.012, freq: 5000, q: 2 });
  }
}

content.text:
Now the main game.js. This is the big part. Let's carefully design and write.

I'll write in sections:

1. Imports, constants, utilities.
2. DOM refs.
3. State variables.
4. Resize, canvas.
5. Audio.
6. Initialization/title UI.
7. Start run/reset.
8. Player creation.
9. Spawning.
10. Update loop.
11. Combat/weapons.
12. Pickups/loot.
13. Level up.
14. HUD.
15. Render.
16. Input.
17. Boot.

Let me draft mentally then write. Need avoid syntax errors.

Utilities:
```
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const rand=(a=0,b=1)=>a+Math.random()*(b-a);
const randInt=(a,b)=>Math.floor(rand(a,b+1));
const pick=arr=>arr[Math.floor(Math.random()*arr.length)];
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const dist2=(x1,y1,x2,y2)=>...
const angleTo=(a,b)=>Math.atan2(b.y-a.y,b.x-a.x);
const norm=(x,y)=>{...}
const formatTime=...
```
Color:
```
function rgba(hex,a){ ... }
function lighten(hex,amt){...}
```
Could use color strings mostly with globalAlpha rather than parse; for rgba need. Implement hex parse.

State:
```
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d',{alpha:false});
let W=0,H=0,DPR=1;
let zoom=1;
const sound=new SoundEngine();
let state='title';
let selectedChar=CHARACTERS[0];
let player=null;
let enemies=[], projectiles=[], enemyShots=[], gems=[], loot=[], heals=[], particles=[], texts=[], rings=[], beams=[], effects=[];
let camera={x:0,y:0,shake:0,shakeX:0,shakeY:0};
let run=null;
let hitStop=0;
let flash={a:0,color:'#fff'};
let ambient=[];
let hudCache={};
let lastTime=0;
let gameOverTimer=0;
let pendingLevelTimer=0;
let titleTime=0;
let lowHpPulse=0;
```

`run` object:
```
{
 time:0, wave:1, kills:0, level:1, xp:0, xpNext:8, pending:0,
 spawnTimer:0.4, waveTimer:0, bossTimer:60, eliteTimer:35, nextBoss:60,
 boss:null, best:null, score:0, startCharacter:selectedChar.id,
 relicCounts:{}, relicOrder:[], weaponCards...
}
```
Actually wave computed; use run.wave and nextWaveAt.
- `run.nextWaveAt = 25`
- `run.nextBossAt = 60`
- `run.nextEliteAt = 30`
- `run.spawnTimer = 0.5`
- `run.pendingLevels=0`
- `run.damageDealt=0`
- `run.time=0`

Player:
```
function createPlayer(char) {
 const s = char.stats;
 const p = {
  char, x:0,y:0,vx:0,vy:0,r:16,
  maxHp:s.maxHp, hp:s.maxHp, baseSpeed:s.speed,
  speedMul:1, damageMul:s.damage, attackSpeed:s.attackSpeed, areaMul:s.area,
  critChance:s.crit, critMult:s.critMult, pickupMul:1, basePickup:s.pickup,
  xpMul:s.xpGain, luck:s.luck, armor:s.armor, regen:s.regen,
  bonusProjectiles:0, lifesteal:0, igniteChance:0, igniteDamage:0,
  frost:0, novaChance:0, novaDamage:0, chainHits:0, execute:0, cooldownMul:1,
  stormLevel:0, stormTimer:3.5, lootMagnet:false,
  abilityCd:0, abilityMax:ABILITIES[char.ability].cooldown,
  guardTimer:0, guardPulse:0, shield:0, overdriveTimer:0,
  invuln:0, facing:{x:0,y:1}, moving:false,
  weapons:[{type:char.weapon, level:1, timer:0.2, spin:0}],
  thornCd:new Map()? can't serialize. Use enemy property e.thornCd.
  trailTimer:0,
  hitFlash:0
 };
 return p;
}
```
- pickup radius = basePickup * pickupMul.
- maybe `xpMul` is 1.0; if char xpGain 1.05.

Camera initial x=0,y=0, zoom computed.

Game state title: Build title cards. ambient array init.

Event listeners:
- `window.addEventListener('resize', resize)`
- keydown/up.
- playBtn click: sound.init(); sound.ui(); startRun(selectedChar).
- char card click delegated on charGrid: find closest `[data-char]`, select.
- abilityBtn pointerdown/click -> useAbility.
- pauseBtn -> togglePause.
- soundBtn -> toggleSound.
- resumeBtn, quitBtn, retryBtn, changeBtn.
- joystick pointer events.
- maybe canvas pointerdown for ability on right click? `contextmenu` prevent.
- window blur -> pause if playing? Could pause. Nice: if document hidden, pause.

Joystick:
```
let joy={active:false,id:null,x:0,y:0};
function joyStart(e){ if(state!=='playing') return; joy.active=true; joy.id=e.pointerId; joyEl.setPointerCapture(e.pointerId); joyMove(e); }
function joyMove(e){ if(!joy.active||e.pointerId!==joy.id)return; const rect=joyEl.getBoundingClientRect(); const cx=rect.left+rect.width/2; ... const dx=e.clientX-cx, dy=...; const max=rect.width*0.32; const len=Math.hypot; const k=Math.min(1,len/max); joy.x=dx/len*k; joy.y=dy/len*k; knob.style.transform=`translate(${joy.x*max}px,${joy.y*max}px)`; e.preventDefault();}
function joyEnd(e){ if(e.pointerId!==joy.id)return; joy.active=false; joy.id=null; joy.x=0;joy.y=0; knob transform 0; }
```
- Also on desktop maybe keyboard.
- Ability button: `click` listener; on touch pointerdown prevent double. Use click.
- Joystick base maybe CSS size 128; knob moves max 44.

Input vector:
```
function getMoveInput() {
 let x=0,y=0;
 if(keys.has('w')||keys.has('arrowup')) y-=1; ...
 if(joy.active){x+=joy.x;y+=joy.y;}
 const len=Math.hypot(x,y); if(len>1){x/=len;y/=len;}
 return {x,y};
}
```
If keyboard + joystick both, normalize.

Keydown:
```
if (state==='title') { if(e.key==='Enter'||e.key===' ') {startRun(selectedChar)} }
if (state==='gameover') ...
if (state==='levelup') { if(['1','2','3'].includes(e.key)) chooseUpgrade(Number(e.key)-1); }
if (e.key==='Escape'||e.key.toLowerCase()==='p') togglePause();
if (e.key==='m') toggleSound();
if (state==='playing' && (e.code==='Space')) {e.preventDefault(); useAbility();}
```
Need if typing? no inputs.
- prevent default for arrows/space only when game states.

State transitions:
- `startRun`: if sound ctx init; set state playing; hide screens; show HUD; reset arrays; run=...; player=createPlayer; camera; spawn initial enemies (maybe 3 at radius 400) and initial loot; hide hint after delay using setTimeout; updateHud immediately; show wave banner.
- `showScreen(id)` / `hideAllScreens`.
- Title: show title, hide HUD.
- `endRun`: state gameover; sound.death; hud maybe; update best; populate gameover; show. Also burst.
- `abandonRun`: show title, hide hud, state title, reset arrays? Maybe keep background. `toTitle()`.
- `togglePause`: if playing -> paused and show overlay; if paused -> playing hide. Music? sound.playing false.
- On level up: `state='levelup'`, show overlay, build cards. `sound.levelup()`; flash gold; shake.
- `chooseUpgrade(index)`: get current choices; apply; hide overlay; run.pendingLevels--; update HUD; if pending > 0 then setTimeout(() => showLevelUp(), 180); else state='playing'. Use `levelupChoices` global.
- Avoid if state changed.

`startRun` should set `document.body.classList.add('in-run')`? CSS maybe.
- hide `hint` after 4s.

Spawner:
```
function updateSpawner(dt) {
 if (run.time >= run.nextWaveAt) { run.wave++; run.nextWaveAt += 25; waveBanner(...); sound.wave(); burstSpawn(6); }
 if (run.time >= run.nextEliteAt && run.time > 30) { spawnEnemy('elite'); run.nextEliteAt += rand(24,34); }
 if (run.time >= run.nextBossAt) { spawnBoss(); run.nextBossAt += 70; }
 run.spawnTimer -= dt;
 if (run.spawnTimer <= 0) {
   const intensity = 1 + run.time/90;
   const interval = Math.max(0.18, 0.75 - run.time*0.0024) * rand(0.8,1.2);
   run.spawnTimer = interval;
   let count = 1 + Math.floor(run.time/55) + (Math.random()<0.3?1:0);
   if (enemies.length > cap) count=0;
   for...
 }
}
```
Wave banner at start: `showBanner('WAVE 1', 'SURVIVE', 'wave')` maybe start run. At each wave.
- `spawnEnemy(type, opts)` chooses type based on time:
```
const pool=[grunt]; if(time>18) runner; if(time>42) tank; if(time>58) shooter; if(time>85) splitter; weights.
```
- If elite, base type random from unlocked, then elite flag.
- Spawn position ring radius `max(W,H)/zoom*0.55 + 100` around player? At mobile zoom 0.7, W/zoom=557, half=278 + 100=378. Good. At desktop 1440/1.35=1066 half 533+100=633. Good. Use `spawnRadius = Math.hypot(W,H)/2/zoom + 90` maybe too far. Use max(W,H)/2/zoom + 100. At 1440, 533+100=633. Fine.
- Angle random. Add jitter.
- Elite spawn slightly bigger.
- Boss spawn at 600.
- `enemies.push(makeEnemy(...))`.

Enemy object:
```
{
 type, cfg, x,y, r, hp,maxHp, speed, damage, xp, color, accent,
 vx,vy, kx,ky, hitFlash:0, contactCd:0, slowTimer:0, slowAmt:0,
 burn:0, burnDps:0, burnTick:0, dead:false,
 elite, boss, name, phase: rand(0,TAU), shootCd: rand(1,2.5),
 thornCd:0, spawnTime:0, wobble: rand(0,TAU), targetAngle...
}
```
- For boss, `name` from BOSS_NAMES index, `bossIndex`.
- Elite scale.

Scale:
```
const t=run.time;
const hpScale=1 + t*0.018 + (run.wave-1)*0.085;
const dmgScale=1 + t*0.006 + (run.wave-1)*0.04;
const spdScale=1 + Math.min(0.3, t*0.0012);
hp = cfg.hp*hpScale*(elite?6:1)
speed = cfg.speed*spdScale*(elite?0.92:1)
damage = cfg.damage*dmgScale*(elite?1.5:1)
r = cfg.radius*(elite?1.3:1)
xp = cfg.xp*(elite?8:1)
```
Boss: hp = 1450*(1+t*0.022+wave*0.12), damage etc.
- Add scaling with wave.

Enemy update:
```
function updateEnemies(dt) {
 for e of enemies {
  if(e.dead) continue;
  e.hitFlash=Math.max(0,e.hitFlash-dt);
  e.contactCd=Math.max(0,e.contactCd-dt);
  e.thornCd=Math.max(0,e.thornCd-dt);
  e.spawnTime+=dt;
  // burn
  if(e.burn>0){ e.burn-=dt; e.burnTick-=dt; if(e.burnTick<=0){e.burnTick=0.35; damageEnemy(e, e.burnDps*0.35, {silent:true, noCrit:true, source:'burn', color:'#ff8a5b'}); } if(e.hp<=0) continue; }
  // slow
  let slow=1; if(e.slowTimer>0){e.slowTimer-=dt; slow=1-e.slowAmt;}
  // AI
  const dx=player.x-e.x, dy=..., d=...
  let mx=0,my=0;
  if(e.cfg.ranged){ if(d>320) {mx=dx/d;my=dy/d} else if(d<230) {mx=-dx/d;...} else {strafe} e.shootCd-=dt; if(e.shootCd<=0 && d<520){shoot...} }
  else if(e.boss){ ... } else { mx=dx/d; my=dy/d; }
  // wobble
  const wob=Math.sin(run.time*4+e.wobble)*0.15 for runner etc.
  e.x += (mx*e.speed*slow + e.kx)*dt; ...
  e.kx*=Math.pow(0.02,dt)? Better `e.kx = lerp(e.kx,0,1-Math.exp(-8*dt))`.
  // contact
  if(d < e.r+player.r && e.contactCd<=0) { damagePlayer(e.damage, e); e.contactCd=0.8; }
 }
 // separation
 ...
 enemies = enemies.filter(e=>!e.dead);
}
```
Boss AI:
- `e.phaseTimer -= dt`
- radial burst every 3.2s:
```
if(e.phaseTimer<=0){ e.phaseTimer=3.2; radialBurst(e, 10); sound.bossShot?}
```
- summon every 9s.
- maybe charge every 7s: set `e.charging=0.7`, telegraph. Could skip.
- Move toward player at speed; occasionally lunge.
- Add slow aura? no.
- Boss contact damage.

Separation:
```
for i... for j=i+1...
 if dx*dx+dy*dy < (ri+rj)^2*0.6 { push }
```
Need account dead.
- To reduce cost, skip boss? no.

Player update:
- `if(!player) return`
- timers.
- movement smoothing: target = input * speed. `player.vx = lerp(player.vx, targetX, 1-Math.exp(-12*dt))` etc. Add knockback separately? Use `player.kx`? Add `player.ivx` impulse. Simpler: movement directly from input and small inertia. Contact knockback adds to vx and decays. Use `player.kx`.
```
const input = getMoveInput();
const speed = player.baseSpeed * player.speedMul * (overdrive?1.35:1) * (guard?0.85:1);
player.vx = lerp(player.vx, input.x*speed, 1-Math.exp(-14*dt));
...
player.x += (player.vx + player.kx)*dt;
player.kx = lerp(player.kx,0,1-Math.exp(-10*dt));
```
- Facing if input nonzero.
- Regen.
- Ability cooldown.
- Stormheart: if stormLevel>0, timer -= dt; if <=0 -> cast chain at nearest with chains 3+stormLevel, damage 20*stormLevel*damageMul?; timer=3.5.
- Guard pulse: if guardTimer>0, decrement, guardPulse -= dt; if <=0 damage enemies within 90+level etc, spawn ring; guardPulse=.45; if guardTimer<=0 shield=0.
- Overdrive timer decrement.
- Invuln decrement.
- Weapons:
  - `for (const w of player.weapons) updateWeapon(w, dt)`
  - For thorn, spin += speed*dt; collision.
  - For aura, timer -= dt*attackSpeed? getWeaponStats already cooldown divided by attackSpeed; but timer update should subtract dt not dt*attackSpeed. Use `w.timer -= dt`. On fire set `w.timer = stats.cooldown`. For thorn/aura, same.
  - For weapon level 1, timer starts 0.2.
- Pickup collection.
- Trail particles when moving.
- Low HP pulse.

Weapon update:
```
function updateWeapon(w, dt) {
 const stats=getWeaponStats(w.type,w.level,player);
 if(w.type==='thorn'){ w.spin += stats.speed*dt; checkOrbitHits(stats); return; }
 if(w.type==='flame'){ w.timer -= dt; if(w.timer<=0){ w.timer = stats.cooldown; auraPulse(stats);} return; }
 w.timer -= dt;
 if(w.timer<=0) {
   const target=nearestEnemy(player.x,player.y,stats.range);
   if(!target) { w.timer = 0.1; return; }
   w.timer = stats.cooldown;
   fireWeapon(w, stats, target);
 }
}
```
- `fireWeapon`:
  - bolt: for i<count, spread small; direction to target + i offset; spawn projectile. If count >1, slight spread. Homing.
  - scatter: angle to target, spread; count shards; spawn.
  - chain: chainLightning(target, stats).
  - boomerang: spawn count boomerangs with spread offsets, `mode:'out'`, `outTime` etc.
  - sound.shoot.
- `spawnProjectile` object:
```
{ x,y, vx,vy, r, damage, pierce, life, maxLife, color, kind:'bolt'|'shard'|'chakram', homing, target, hitSet:new Set(), trailTimer, angle, spin, returning:false, origin...}
```
- For bolt homing: find nearest target each frame within range; turn velocity toward target with max turn rate.
- For chakram: out for 0.45s, then return to player, hit cooldown per enemy? use hitSet and pierce infinite? We can have hitSet reset when returning? Simpler `pierce=999` but hitSet prevents multi hit same enemy; on return maybe clear. We'll implement `p.hitSet` and `p.pierce=999`, `p.life=1.4`.
- Damage on hit.
- Projectiles update:
```
for p of projectiles:
 p.life-=dt;
 if(p.kind==='chakram'){ p.spin += 14*dt; if(p.mode==='out'){p.outT-=dt; if(p.outT<=0)p.mode='back';} if(p.mode==='back'){ turn toward player strongly; if close remove } }
 if(p.homing){ target nearest...; steer }
 p.x+=vx*dt...
 // trail
 // collision
 for e of enemies: if(!dead && !hitSet.has(e) && dist<...) { hitSet.add; damage; pierce--; if(pierce<0) dead }
```
- Use `p.dead` and filter.
- If offscreen far > 2000? remove.
- Add glow.

`hitEnemy(e, amount, options)`:
- options: crit? canCrit, source, color, noText, knockback, lifesteal.
- Compute crit.
- damage amount * crit.
- execute if e.hp/maxHp < 0.3.
- `e.hp -= dmg`; player lifesteal heal.
- hitFlash.
- `addText`.
- `spawnSparks`.
- `sound.hit(crit || amount>30)`.
- status: if source not burn and player.igniteChance > 0 and random < chance -> e.burn = 2.2; e.burnDps = (4 + player.igniteDamage + player.damageMul*3) maybe; e.burnTick=0.35.
- frost: e.slowTimer=1.8; e.slowAmt=player.frost.
- chain chance? We have chainHits passive: on hit, maybe if player.chainHits>0 and random<0.2 -> chain to nearby for 50% dmg. Implement with a cooldown? Could get crazy. Maybe `if (player.chainHits>0 && Math.random()<0.18) chainBolt(e, player.chainHits, dmg*0.45)`. Good.
- knockback: e.kx += dx/d * 40.
- if hp<=0 killEnemy.

`killEnemy(e, opts)`:
- if e.dead return; e.dead=true; run.kills++;
- particles explosion color.
- ring.
- screen shake if elite/boss.
- XP gem(s).
- loot.
- splitter spawns 2 small enemies? Need avoid recursively within loop; push to enemies after? Use `pendingSpawns` array processed next frame, or push directly (fine but iteration includes new maybe). We can push directly with `spawnEnemy('runner', {x,y, small:true})` but would also scale. Fine.
- nova chance: if random < novaChance -> explode(e.x,e.y, damage 18+novaDamage, radius 90). `explode` damages nearby enemies, particles, ring, shake.
- boss death: huge explosion, drop many loot, heal player, remove boss bar, show banner "BOSS SLAIN", sound.
- `enemies = enemies.filter` after update. But killEnemy can be called during projectile loop; dead flag prevents.
- XP gems: value = e.xp; maybe split into one gem with value. For boss spawn 20 gems around. For elite spawn 5 gems.
- Loot: `maybeDropLoot(e)`.
- Health: chance 3% or 12% if low hp? spawn heal.
- Combo? no.

`explode(x,y,damage,radius,color)`:
- iterate enemies within radius, hitEnemy(e, damage, {noCrit? false, source:'nova', color, noChain?})
- ring, particles, shake, sound.explode.
