:root {
  --bg: #05070d;
  --ink: #eef6ff;
  --muted: #8b9bb8;
  --cyan: #63e7ff;
  --violet: #a78bfa;
  --pink: #ff5d8f;
  --gold: #ffc857;
  --green: #6ee7a0;
  --orange: #ffb45e;
  --panel: rgba(8, 13, 24, 0.78);
  --line: rgba(138, 178, 255, 0.17);
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  --font: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --display: "Arial Black", "Trebuchet MS", Impact, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; }
html { background: var(--bg); }
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
button { font: inherit; color: inherit; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}
#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 36%, rgba(1, 3, 8, 0.34) 74%, rgba(0, 0, 0, 0.68) 100%),
    linear-gradient(180deg, rgba(4, 7, 14, 0.18), transparent 18%, transparent 76%, rgba(4, 7, 14, 0.42));
  transition: background 0.4s ease;
}
#vignette::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.12;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 3px);
  mix-blend-mode: soft-light;
}
body.low-hp #vignette {
  background:
    radial-gradient(ellipse at 50% 50%, transparent 28%, rgba(140, 0, 32, 0.24) 72%, rgba(90, 0, 20, 0.55) 100%),
    linear-gradient(180deg, rgba(40, 0, 8, 0.15), transparent 22%, transparent 70%, rgba(40, 0, 8, 0.35));
  animation: lowHp 1.15s ease-in-out infinite;
}

/* ==========================================================================
   HUD
   ========================================================================== */
#hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
.panel {
  background: linear-gradient(180deg, rgba(13, 20, 36, 0.86), rgba(7, 11, 21, 0.82));
  border: 1px solid var(--line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.045);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}

.hud-top {
  position: absolute;
  top: max(12px, env(safe-area-inset-top));
  left: max(14px, env(safe-area-inset-left));
  right: max(14px, env(safe-area-inset-right));
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}
.hud-left {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 322px;
  padding: 9px 12px 9px 9px;
  border-radius: 5px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.portrait {
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 22px;
  color: var(--c, var(--cyan));
  border: 1px solid var(--c, var(--cyan));
  background:
    radial-gradient(circle at 36% 28%, rgba(255,255,255,0.35), transparent 24%),
    radial-gradient(circle at 50% 55%, var(--c, var(--cyan)), rgba(4, 8, 16, 0.92) 68%);
  box-shadow: 0 0 22px color-mix(in srgb, var(--c, var(--cyan)) 45%, transparent), inset 0 0 14px rgba(0,0,0,0.5);
  text-shadow: 0 1px 8px rgba(0,0,0,0.7);
}
.meta { flex: 1; min-width: 0; }
.meta-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
