/* ==========================================================================
   TOUCH JOYSTICK
   ========================================================================== */
.joystick {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(18px, env(safe-area-inset-bottom));
  width: 128px;
  height: 128px;
  border-radius: 50%;
  z-index: 8;
  display: none;
  touch-action: none;
  background: radial-gradient(circle, rgba(99,231,255,0.07), transparent 66%);
}
.joy-ring {
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  border: 1px solid rgba(99, 231, 255, 0.25);
  box-shadow: inset 0 0 28px rgba(99, 231, 255, 0.06), 0 0 24px rgba(0,0,0,0.35);
}
.joy-ring::after {
  content: "";
  position: absolute;
  inset: 23px;
  border-radius: 50%;
  border: 1px dashed rgba(167, 139, 250, 0.15);
}
.joy-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  margin: -24px 0 0 -24px;
  border-radius: 50%;
  border: 1px solid rgba(99, 231, 255, 0.6);
  background: radial-gradient(circle at 36% 30%, rgba(255,255,255,0.32), rgba(99,231,255,0.28) 35%, rgba(8,16,28,0.9) 72%);
  box-shadow: 0 0 24px rgba(99, 231, 255, 0.28), inset 0 0 14px rgba(0,0,0,0.55);
  pointer-events: none;
}

