+  padding: 2px 5px;
+  border: 1px solid color-mix(in srgb, var(--c) 38%, transparent);
+  color: var(--c);
+  font-size: 6px;
+  font-weight: 900;
+  letter-spacing: 0.12em;
+  border-radius: 2px;
+}
+.char-epithet { margin-top: 1px; color: var(--muted); font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; }
+.char-loadout {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  margin-top: 8px;
+  padding-top: 7px;
+  border-top: 1px solid rgba(139, 176, 235, 0.1);
+  color: #cfdcef;
+  font-size: 9px;
+  letter-spacing: 0.06em;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.char-loadout.ability { margin-top: 3px; padding-top: 0; border-top: 0; color: #aebbd0; }
+.loadout-icon { color: var(--c); font-size: 12px; text-shadow: 0 0 9px var(--c); }
+.char-bars { display: flex; flex-direction: column; gap: 4px; margin-top: 9px; }
+.char-bar { display: flex; align-items: center; gap: 7px; }
+.char-bar span { width: 35px; color: #7485a1; font-size: 6px; font-weight: 900; letter-spacing: 0.1em; }
+.char-bar i { flex: 1; height: 3px; background: rgba(4, 7, 14, 0.9); overflow: hidden; }
+.char-bar b { display: block; height: 100%; background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, transparent), var(--c)); box-shadow: 0 0 8px var(--c); }
+
+.title-actions { display: flex; flex-direction: column; align-items: center; gap: 8px; margin-top: 15px; }
+.btn {
+  position: relative;
+  min-width: 170px;
+  padding: 12px 26px;
+  border: 1px solid rgba(138, 178, 255, 0.28);
+  background: rgba(10, 16, 28, 0.75);
+  color: #d7e7fb;
+  font-family: var(--display);
+  font-size: 13px;
+  letter-spacing: 0.16em;
+  text-transform: uppercase;
+  cursor: pointer;
+  border-radius: 3px;
+  transition: 0.18s ease;
+  overflow: hidden;
+}
+.btn:hover { transform: translateY(-1px); border-color: var(--cyan); color: #fff; box-shadow: 0 0 24px rgba(99, 231, 255, 0.16); }
+.btn-primary {
+  min-width: 240px;
+  padding: 15px 34px;
+  font-size: 17px;
+  color: #041018;
+  border: 0;
+  background: linear-gradient(100deg, #7ff4ff, #63e7ff 40%, #a78bfa 100%);
+  box-shadow: 0 0 34px rgba(99, 231, 255, 0.35), 0 10px 26px rgba(0,0,0,0.42);
+}
+.btn-primary::after {
+  content: "";
+  position: absolute;
+  top: -60%;
+  left: -30%;
+  width: 26%;
+  height: 220%;
+  transform: rotate(18deg);
+  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.55), transparent);
+  animation: shine 3.4s ease-in-out infinite;
+}
+.btn-primary:hover { box-shadow: 0 0 50px rgba(99, 231, 255, 0.52), 0 12px 30px rgba(0,0,0,0.5); }
+.best { color: #7f8fab; font-size: 8px; font-weight: 800; letter-spacing: 0.2em; }
+.title-foot {
+  display: flex;
+  justify-content: center;
+  flex-wrap: wrap;
+  gap: 8px 24px;
+  margin-top: 12px;
+  color: #5c6b86;
+  font-size: 7px;
+  font-weight: 800;
+  letter-spacing: 0.18em;
+}
+.title-foot span:last-child { color: #697a98; }
+
+/* ==========================================================================
+   OVERLAYS
+   ========================================================================== */
+.overlay {
+  z-index: 30;
+  background: rgba(3, 6, 12, 0.72);
+  backdrop-filter: blur(7px);
+  -webkit-backdrop-filter: blur(7px);
+}
+.overlay-card {
+  position: relative;
+  width: min(1000px, 94vw);
+  padding: clamp(18px, 3vw, 36px);
+  text-align: center;
+  border: 1px solid rgba(137, 178, 255, 0.22);
+  border-radius: 6px;
+  background:
+    radial-gradient(ellipse at 50% -10%, rgba(99, 231, 255, 0.09), transparent 45%),
+    linear-gradient(180deg, rgba(13, 21, 38, 0.97), rgba(6, 10, 19, 0.98));
+  box-shadow: 0 40px 100px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,255,255,0.06);
+  overflow: hidden;
+  animation: overlayIn 0.28s cubic-bezier(.2,.9,.2,1.1) both;
+}
+.overlay-card::before {
+  content: "";
+  position: absolute;
+  left: 10%;
+  right: 10%;
+  top: 0;
+  height: 1px;
+  background: linear-gradient(90deg, transparent, var(--cyan), var(--violet), transparent);
+  opacity: 0.75;
+}
+.kicker {
+  color: var(--cyan);
+  font-size: 9px;
+  font-weight: 900;
+  letter-spacing: 0.4em;
+  text-transform: uppercase;
+}
+.kicker.gold { color: var(--gold); text-shadow: 0 0 18px rgba(255,200,87,0.55); }
+.overlay-card h2 {
+  margin: 7px 0 3px;
+  font-family: var(--display);
+  font-size: clamp(26px, 4vw, 48px);
+  line-height: 0.95;
+  letter-spacing: 0.035em;
+  text-transform: uppercase;
+  background: linear-gradient(180deg, #ffffff, #c6e9ff 55%, #7ea4d8);
+  -webkit-background-clip: text;
+  background-clip: text;
+  -webkit-text-fill-color: transparent;
+  filter: drop-shadow(0 4px 16px rgba(0,0,0,0.5));
+}
+.overlay-sub { margin: 5px 0 16px; color: var(--muted); font-size: 10px; letter-spacing: 0.13em; }
+.overlay-hint { margin-top: 12px; color: #64748d; font-size: 8px; font-weight: 800; letter-spacing: 0.3em; }
+
+.upgrade-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
+.upgrade-card {
+  position: relative;
+  min-height: 224px;
+  padding: 16px 16px 14px;
+  text-align: left;
+  border: 1px solid color-mix(in srgb, var(--c) 48%, transparent);
+  border-radius: 5px;
+  background:
+    linear-gradient(180deg, rgba(18, 27, 46, 0.94), rgba(7, 11, 20, 0.96)),
+    radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--c) 12%, transparent), transparent 60%);
+  box-shadow: 0 16px 36px rgba(0,0,0,0.36), inset 0 0 30px color-mix(in srgb, var(--c) 5%, transparent);
+  cursor: pointer;
+  overflow: hidden;
+  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
+  animation: cardIn 0.32s cubic-bezier(.2,.9,.2,1.08) both;
+}
+.upgrade-card:nth-child(2) { animation-delay: 0.05s; }
+.upgrade-card:nth-child(3) { animation-delay: 0.1s; }
+.upgrade-card:hover, .upgrade-card:focus-visible {
+  transform: translateY(-5px);
+  border-color: var(--c);
+  box-shadow: 0 0 0 1px color-mix(in srgb, var(--c) 55%, transparent), 0 20px 46px rgba(0,0,0,0.48), 0 0 34px color-mix(in srgb, var(--c) 18%, transparent);
+  outline: none;
+}
+.upgrade-glow {
+  position: absolute;
+  inset: auto -20% -50% -20%;
+  height: 60%;
+  background: radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--c) 20%, transparent), transparent 66%);
+  pointer-events: none;
+}
+.upgrade-key {
+  position: absolute;
+  right: 10px;
+  top: 10px;
+  width: 22px;
+  height: 22px;
+  display: grid;
+  place-items: center;
+  border: 1px solid color-mix(in srgb, var(--c) 30%, transparent);
+  color: #8090aa;
+  font-family: var(--mono);
+  font-size: 9px;
+  border-radius: 2px;
+}
+.upgrade-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; }
+.upgrade-icon {
+  width: 48px;
+  height: 48px;
+  display: grid;
+  place-items: center;
+  border: 1px solid color-mix(in srgb, var(--ic) 58%, transparent);
+  border-radius: 50%;
+  color: var(--ic);
+  font-size: 24px;
+  background: radial-gradient(circle at 40% 32%, rgba(255,255,255,0.12), color-mix(in srgb, var(--ic) 12%, transparent) 38%, rgba(5,9,17,0.9) 72%);
+  box-shadow: 0 0 20px color-mix(in srgb, var(--ic) 25%, transparent), inset 0 0 14px rgba(0,0,0,0.5);
+  text-shadow: 0 0 14px var(--ic);
+}
+.upgrade-tier { color: var(--c); font-size: 8px; font-weight: 900; letter-spacing: 0.24em; }
+.upgrade-name { display: block; font-family: var(--display); font-size: 20px; letter-spacing: 0.02em; text-transform: uppercase; color: #f2f8ff; }
+.upgrade-meta { display: block; margin-top: 4px; color: var(--c); font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; }
+.upgrade-desc { display: block; margin-top: 10px; padding-top: 10px; border-top: 1px solid rgba(139,176,235,0.11); color: #aab9cf; font-size: 11px; line-height: 1.5; }
+.tier-4 { animation: cardIn 0.32s cubic-bezier(.2,.9,.2,1.08) both, legendaryCard 2.4s ease-in-out infinite 0.4s; }
+
+.small-card { width: min(520px, 92vw); }
+.pause-actions, .gameover-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 9px; margin-top: 18px; }
+.gameover-card { width: min(780px, 94vw); }
+.gameover-card h2 { background: linear-gradient(180deg, #fff, #ffb3c0 58%, #ff5d73); -webkit-background-clip: text; background-clip: text; }
+.stats-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 7px;
+  margin: 14px 0;
+}
+.stats-grid div {
+  padding: 9px 8px;
+  border: 1px solid rgba(139,176,235,0.12);
+  background: rgba(5, 9, 17, 0.55);
+  text-align: left;
+}
+.stats-grid span { display: block; color: #6f809a; font-size: 7px; font-weight: 900; letter-spacing: 0.18em; }
+.stats-grid b { display: block; margin-top: 3px; font-family: var(--mono); font-size: 17px; color: #e9f4ff; }
+.loot-summary { display: flex; justify-content: center; flex-wrap: wrap; gap: 6px; }
+.loot-pill {
+  padding: 4px 8px;
+  border: 1px solid color-mix(in srgb, var(--c) 40%, transparent);
+  color: var(--c);
+  background: color-mix(in srgb, var(--c) 7%, transparent);
+  font-size: 7px;
+  font-weight: 900;
+  letter-spacing: 0.13em;
+  border-radius: 2px;
+}
+
+/* ==========================================================================
+   RESPONSIVE
+   ========================================================================== */
+@media (max-width: 1080px) {
+  .char-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .title-wrap { width: min(760px, 94vw); }
+  .char-card { min-height: 168px; }
+}
+
+@media (max-width: 900px), (pointer: coarse) {
+  .joystick { display: block; }
+  .weapon-strip { display: none; }
+  .hud-top { top: max(8px, env(safe-area-inset-top)); left: max(8px, env(safe-area-inset-left)); right: max(8px, env(safe-area-inset-right)); gap: 7px; }
+  .hud-left { width: 172px; padding: 7px 8px 7px 7px; gap: 8px; }
+  .portrait { width: 34px; height: 34px; font-size: 17px; }
+  .hud-name { font-size: 11px; }
+  .level { font-size: 8px; padding: 1px 4px; }
+  .meta-row.sub { display: none; }
+  .xpbar { height: 5px; margin-top: 4px; }
+  .hud-center { min-width: 92px; padding-top: 2px; }
+  .timer { font-size: 24px; }
+  .wave { font-size: 8px; letter-spacing: 0.22em; }
+  .hud-right { gap: 4px; }
+  .icon-btn { width: 32px; height: 32px; font-size: 11px; }
+  .bossbar {
+    position: fixed;
+    top: calc(62px + env(safe-area-inset-top));
+    left: max(10px, env(safe-area-inset-left));
+    right: max(10px, env(safe-area-inset-right));
+    width: auto;
+    margin: 0;
+  }
+  .hud-bottom { left: 0; right: 0; bottom: 0; display: block; }
+  .vitals {
+    position: fixed;
+    left: max(10px, env(safe-area-inset-left));
+    right: max(10px, env(safe-area-inset-right));
+    bottom: calc(146px + env(safe-area-inset-bottom));
+    width: auto;
+    padding: 8px 10px 7px;
+  }
+  .ability {
+    position: fixed;
+    right: max(18px, env(safe-area-inset-right));
+    bottom: calc(18px + env(safe-area-inset-bottom));
+    width: 72px;
+    height: 72px;
+  }
+  .ability-icon { font-size: 27px; }
+  .relic-strip {
+    left: max(10px, env(safe-area-inset-left));
+    right: max(10px, env(safe-area-inset-right));
+    bottom: calc(208px + env(safe-area-inset-bottom));
+    transform: none;
+    max-width: none;
+    justify-content: flex-start;
+    gap: 4px;
+  }
+  .relic-chip { width: 25px; height: 25px; font-size: 12px; }
+  .hint { bottom: calc(258px + env(safe-area-inset-bottom)); font-size: 8px; white-space: normal; width: min(320px, 86vw); text-align: center; }
+  .toast-layer { top: calc(92px + env(safe-area-inset-top)); width: min(330px, 92vw); }
+  .toast { min-width: 210px; padding: 7px 10px 7px 7px; }
+  .toast-icon { width: 30px; height: 30px; font-size: 16px; }
+  .toast-copy strong { font-size: 12px; }
+  .toast-copy small { font-size: 9px; }
+  .banner-title { font-size: clamp(28px, 9vw, 48px); }
+  .banner-sub { font-size: 8px; letter-spacing: 0.3em; }
+  .wave-banner { top: 28%; }
+  .overlay { align-items: flex-start; padding-top: max(18px, env(safe-area-inset-top)); }
+  .overlay-card { margin: auto 0; }
+}
+
+@media (max-width: 640px) {
+  .title-wrap { width: 94vw; padding-top: 2px; }
+  .eyebrow { font-size: 7px; letter-spacing: 0.32em; margin-bottom: 6px; }
+  .logo { font-size: clamp(54px, 15vw, 78px); }
+  .logo-sub { font-size: 9px; letter-spacing: 0.9em; text-indent: 0.9em; margin-top: 2px; }
+  .tagline { margin: 7px auto 11px; font-size: 9px; }
+  .char-grid { gap: 6px; }
+  .char-card { min-height: 142px; padding: 9px 9px 8px; }
+  .char-orb { width: 34px; height: 34px; font-size: 16px; }
+  .char-name { font-size: 14px; }
+  .char-diff { font-size: 5px; padding: 1px 3px; }
+  .char-epithet { font-size: 7px; }
+  .char-loadout { font-size: 7px; margin-top: 6px; padding-top: 5px; gap: 4px; }
+  .char-loadout.ability { margin-top: 2px; }
+  .loadout-icon { font-size: 10px; }
+  .char-bars { margin-top: 6px; gap: 3px; }
+  .char-bar span { width: 27px; font-size: 5px; }
+  .char-bar i { height: 2px; }
+  .title-actions { margin-top: 11px; gap: 6px; }
+  .btn-primary { min-width: 200px; padding: 12px 28px; font-size: 15px; }
+  .best { font-size: 6px; letter-spacing: 0.14em; }
+  .title-foot { gap: 4px 12px; font-size: 5px; margin-top: 8px; }
+  .upgrade-grid { grid-template-columns: 1fr; gap: 8px; }
+  .upgrade-card { min-height: 0; padding: 11px 12px 10px; }
+  .upgrade-top { margin-bottom: 7px; }
+  .upgrade-icon { width: 38px; height: 38px; font-size: 19px; }
+  .upgrade-name { font-size: 16px; }
+  .upgrade-meta { font-size: 7px; }
+  .upgrade-desc { margin-top: 6px; padding-top: 7px; font-size: 10px; line-height: 1.35; }
+  .upgrade-key { width: 18px; height: 18px; font-size: 8px; }
+  .overlay-card { padding: 15px 12px; width: 94vw; }
+  .overlay-card h2 { font-size: 25px; }
+  .overlay-sub { font-size: 8px; margin-bottom: 10px; }
+  .overlay-hint { margin-top: 8px; font-size: 7px; }
+  .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; margin: 10px 0; }
+  .stats-grid div { padding: 7px 6px; }
+  .stats-grid b { font-size: 14px; }
+  .gameover-actions, .pause-actions { margin-top: 12px; gap: 6px; }
+  .btn { min-width: 140px; padding: 10px 18px; font-size: 11px; }
+  .hud-left { width: 146px; }
+  .hud-name { font-size: 10px; }
+  .timer { font-size: 21px; }
+  .wave { font-size: 7px; }
+  .hud-center { min-width: 78px; }
+  .vitals { bottom: calc(138px + env(safe-area-inset-bottom)); }
+  .relic-strip { bottom: calc(198px + env(safe-area-inset-bottom)); }
+  .hint { bottom: calc(246px + env(safe-area-inset-bottom)); }
+  .ability { width: 66px; height: 66px; }
+  .ability-icon { font-size: 24px; }
+  .joystick { width: 112px; height: 112px; left: max(12px, env(safe-area-inset-left)); }
+  .joy-knob { width: 42px; height: 42px; margin: -21px 0 0 -21px; }
+}
+
+@media (max-height: 760px) and (min-width: 641px) {
+  .char-card { min-height: 150px; }
+  .char-bars { display: none; }
+  .logo { font-size: clamp(54px, 7.5vw, 92px); }
+  .tagline { margin: 6px auto 10px; }
+  .title-actions { margin-top: 10px; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; }
+}
+
+/* ==========================================================================
+   KEYFRAMES
+   ========================================================================== */
+@keyframes lowHp {
+  0%, 100% { opacity: 0.72; }
+  50% { opacity: 1; }
+}
+@keyframes readyPulse {
+  0%, 100% { box-shadow: 0 0 0 5px rgba(6, 10, 19, 0.5), 0 0 26px rgba(99, 231, 255, 0.18); }
+  50% { box-shadow: 0 0 0 5px rgba(6, 10, 19, 0.5), 0 0 42px rgba(99, 231, 255, 0.42); }
+}
+@keyframes legendaryChip {
+  0%, 100% { box-shadow: 0 0 10px rgba(255, 200, 87, 0.2), inset 0 0 10px rgba(0,0,0,0.55); }
+  50% { box-shadow: 0 0 22px rgba(255, 200, 87, 0.6), inset 0 0 10px rgba(0,0,0,0.55); }
+}
+@keyframes toastIn {
+  from { opacity: 0; transform: translateY(-9px) scale(0.97); }
+  to { opacity: 1; transform: translateY(0) scale(1); }
+}
+@keyframes banner {
+  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.9); }
+  14% { opacity: 1; transform: translate(-50%, -50%) scale(1.03); }
+  24% { transform: translate(-50%, -50%) scale(1); }
+  72% { opacity: 1; }
+  100% { opacity: 0; transform: translate(-50%, -54%) scale(1.02); }
+}
+@keyframes overlayIn {
+  from { opacity: 0; transform: translateY(12px) scale(0.98); }
+  to { opacity: 1; transform: translateY(0) scale(1); }
+}
+@keyframes cardIn {
+  from { opacity: 0; transform: translateY(14px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+@keyframes legendaryCard {
+  0%, 100% { box-shadow: 0 16px 36px rgba(0,0,0,0.36), inset 0 0 30px rgba(255, 200, 87, 0.04); }
+  50% { box-shadow: 0 16px 36px rgba(0,0,0,0.36), 0 0 38px rgba(255, 200, 87, 0.18), inset 0 0 40px rgba(255, 200, 87, 0.08); }
+}
+@keyframes shine {
+  0%, 55% { left: -40%; }
+  75%, 100% { left: 120%; }
+}
