function frame(now) {
  const dt = lastFrame ? Math.min(0.05, (now - lastFrame) / 1000) : 0.016;
  lastFrame = now;
  if (state === 'playing') {
    if (hitStop > 0) {
      hitStop = Math.max(0, hitStop - dt);
      flash.a = Math.max(0, flash.a - dt * 2.1);
      updateCamera(dt);
      updateParticles(dt * 0.35);
      updateTexts(dt);
      updateRings(dt);
    } else {
      updateGame(dt);
    }
  } else if (state === 'dying') {
    deathTimer -= dt;
    flash.a = Math.max(0, flash.a - dt * 2.1);
    updateParticles(dt);
    updateTexts(dt);
    updateRings(dt);
    updateCamera(dt);
    if (deathTimer <= 0) endRun();
  } else if (state === 'title') {
    updateAmbient(dt);
  } else if (state === 'gameover') {
    flash.a = Math.max(0, flash.a - dt * 2.1);
    updateParticles(dt * 0.4);
    updateTexts(dt * 0.4);
    updateRings(dt * 0.4);
    updateCamera(dt);
  } else {
    flash.a = Math.max(0, flash.a - dt * 2.1);
  }
  render();
