    }
  }
  for (let i = 0; i < 3; i++) {
    const ang = rand(0, TAU);
    const rr = rand(radius * 0.45, radius);
    spawnParticle(player.x + Math.cos(ang) * rr, player.y + Math.sin(ang) * rr, rand(-15, 15), rand(-55, -20), rand(2, 5), pick(['#ff8a5b', '#ffc857', '#ff5d73']), rand(0.3, 0.7), -20, 0.9, true);
